create table if not exists public.support_tickets(id uuid primary key default gen_random_uuid(),ticket_number bigint generated by default as identity unique,customer_user_id uuid not null references auth.users(id) on delete cascade,customer_name text not null default '',customer_email text not null default '',company_id uuid,company_name text not null default '',assigned_staff_id uuid,assigned_staff_name text not null default '',subject text not null check(char_length(trim(subject)) between 3 and 180),initial_message text not null check(char_length(trim(initial_message)) between 1 and 12000),category text not null default 'general' check(category in('general','complaint','technical','billing','account','suggestion','other')),priority text not null default 'normal' check(priority in('low','normal','high','urgent')),status text not null default 'new' check(status in('new','open','in_progress','awaiting_customer','escalated','resolved','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists support_tickets_customer_updated_idx on public.support_tickets(customer_user_id,updated_at desc);
create index if not exists support_tickets_status_updated_idx on public.support_tickets(status,updated_at desc);
create table if not exists public.support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,sender_user_id uuid references auth.users(id) on delete set null,sender_role text not null check(sender_role in('customer','support')),sender_name text not null default '',body text not null check(char_length(trim(body)) between 1 and 12000),created_at timestamptz not null default now(),customer_read_at timestamptz,staff_read_at timestamptz);
create table if not exists public.support_ticket_events(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,actor_user_id uuid,actor_name text not null default '',event_type text not null,event_details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists support_ticket_events_ticket_created_idx on public.support_ticket_events(ticket_id,created_at desc);
alter table public.support_ticket_events enable row level security;
create index if not exists support_messages_ticket_created_idx on public.support_messages(ticket_id,created_at);
create index if not exists support_messages_unread_customer_idx on public.support_messages(ticket_id,created_at) where sender_role='support' and customer_read_at is null;
alter table public.support_tickets enable row level security;
alter table public.support_messages enable row level security;
drop policy if exists support_tickets_customer_read on public.support_tickets;
create policy support_tickets_customer_read on public.support_tickets for select to authenticated using(customer_user_id=(select auth.uid()));
drop policy if exists support_tickets_customer_create on public.support_tickets;
create policy support_tickets_customer_create on public.support_tickets for insert to authenticated with check(customer_user_id=(select auth.uid()) and status='new' and assigned_staff_id is null and assigned_staff_name='' and resolved_at is null and priority in('low','normal','high'));
drop policy if exists support_messages_customer_read on public.support_messages;
create policy support_messages_customer_read on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid())));
drop policy if exists support_messages_customer_create on public.support_messages;
create policy support_messages_customer_create on public.support_messages for insert to authenticated with check(sender_role='customer' and sender_user_id=(select auth.uid()) and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid())));
drop policy if exists support_messages_customer_mark_read on public.support_messages;
create policy support_messages_customer_mark_read on public.support_messages for update to authenticated using(sender_role='support' and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid()))) with check(sender_role='support' and exists(select 1 from public.support_tickets t where t.id=support_messages.ticket_id and t.customer_user_id=(select auth.uid())));
grant select,insert on public.support_tickets to authenticated;
grant usage,select on sequence public.support_tickets_ticket_number_seq to authenticated;
grant select,insert on public.support_messages to authenticated;
grant all on public.support_tickets,public.support_messages,public.support_ticket_events to service_role;
grant usage,select on sequence public.support_tickets_ticket_number_seq to service_role;
revoke update on public.support_messages from authenticated;
grant update(customer_read_at) on public.support_messages to authenticated;
create or replace function public.support_touch_ticket() returns trigger language plpgsql security definer set search_path=public as $support$ begin update public.support_tickets set updated_at=now(),status=case when new.sender_role='customer' and status in('resolved','closed') then 'open' else status end,resolved_at=case when new.sender_role='customer' and status in('resolved','closed') then null else resolved_at end where id=new.ticket_id; return new; end; $support$;
revoke all on function public.support_touch_ticket() from public, anon, authenticated;
drop trigger if exists support_messages_touch_ticket on public.support_messages;
create trigger support_messages_touch_ticket after insert on public.support_messages for each row execute function public.support_touch_ticket();
